sysauto_script.script:
(function() {
  var engine = new x_snc_testreach.TestReachCoverageEngine();
  var scopeGr = new GlideRecord('sys_app');
  scopeGr.addQuery('vendor_prefix', 'x_');
  scopeGr.addQuery('scope', '!=', 'global');
  scopeGr.addQuery('scope', '!=', 'x_snc_testreach');
  scopeGr.query();
  while (scopeGr.next()) {
    var scope = scopeGr.getValue('scope');
    if (!scope) continue;
    try {
      var result = engine.snapshotCoverage(scope);
      gs.log('TestReach: nightly scan for ' + scope + ' complete. coverage=' +
        result.coverage_pct + '% tested=' + result.tested_count +
        ' untested=' + result.untested_count);
    } catch (e) {
      gs.logError('TestReach: nightly scan failed for ' + scope + ': ' + e.message, 'TestReach');
    }
  }
})();
